static void _get_public_key(b_t *public_key, b_t const *secret_key);
static void _sign(b_t *signature, b_t const *secret_key, b_t const *public_key, b_t const *message, u_t message_size);
static i_t _auth(b_t const *signature, b_t const *public_key, b_t const *message, u_t message_size);

struct espress_cipher_ed25519_ops const espress_cipher_ed25519[] =
{{
	_get_public_key,
	_sign,
	_auth
}};

static i_t _crypto_verify_32(b_t const *x, b_t const *y)
{
	u_t u;
	u = (x[ 0] ^ y[ 0]) |
		(x[ 1] ^ y[ 1]) |
		(x[ 2] ^ y[ 2]) |
		(x[ 3] ^ y[ 3]) |
		(x[ 4] ^ y[ 4]) |
		(x[ 5] ^ y[ 5]) |
		(x[ 6] ^ y[ 6]) |
		(x[ 7] ^ y[ 7]) |
		(x[ 8] ^ y[ 8]) |
		(x[ 9] ^ y[ 9]) |
		(x[10] ^ y[10]) |
		(x[11] ^ y[11]) |
		(x[12] ^ y[12]) |
		(x[13] ^ y[13]) |
		(x[14] ^ y[14]) |
		(x[15] ^ y[15]) |
		(x[16] ^ y[16]) |
		(x[17] ^ y[17]) |
		(x[18] ^ y[18]) |
		(x[19] ^ y[19]) |
		(x[20] ^ y[20]) |
		(x[21] ^ y[21]) |
		(x[22] ^ y[22]) |
		(x[23] ^ y[23]) |
		(x[24] ^ y[24]) |
		(x[25] ^ y[25]) |
		(x[26] ^ y[26]) |
		(x[27] ^ y[27]) |
		(x[28] ^ y[28]) |
		(x[29] ^ y[29]) |
		(x[30] ^ y[30]) |
		(x[31] ^ y[31]);
	return (1 & ((u - 1) >> 8)) - 1;
}

static u_t _eq(struct espress_cipher_uint32 const *a, struct espress_cipher_uint32 const *b)
{
	u_t ret;
	struct espress_cipher_uint32 x[1];
	espress_cipher_uint32_assign(x, a);
	espress_cipher_uint32_xor(x, b);
	espress_cipher_uint32_sub(x, espress_cipher_uint32_1);
	espress_cipher_uint32_shift(x, -31);
	espress_cipher_uint32_get_u(x, &ret);
	return ret;
}

static u_t _lt(struct espress_cipher_uint32 const *a, struct espress_cipher_uint32 const *b)
{
	u_t ret;
	struct espress_cipher_uint32 x[1];
	espress_cipher_uint32_assign(x, a);
	espress_cipher_uint32_sub(x, b);
	espress_cipher_uint32_shift(x, -31);
	espress_cipher_uint32_get_u(x, &ret);
	return ret;
}

static u_t _ge(struct espress_cipher_uint32 const *a, struct espress_cipher_uint32 const *b)
{
	return _lt(a, b) ^ 1;
}

static void _times_19(struct espress_cipher_uint32 *a)
{
	struct espress_cipher_uint32 x[1];
	espress_cipher_uint32_assign(x, a);
	espress_cipher_uint32_shift(x, 1);
	espress_cipher_uint32_add(a, x);
	espress_cipher_uint32_shift(x, 4 - 1);
	espress_cipher_uint32_add(a, x);
}

static void _times_38(struct espress_cipher_uint32 *a)
{
	struct espress_cipher_uint32 x[1];
	espress_cipher_uint32_assign(x, a);
	espress_cipher_uint32_shift(x, 1);
	espress_cipher_uint32_assign(a, x);
	espress_cipher_uint32_shift(x, 2 - 1);
	espress_cipher_uint32_add(a, x);
	espress_cipher_uint32_shift(x, 5 - 2);
	espress_cipher_uint32_add(a, x);
}

struct fe25519
{
	struct espress_cipher_uint32 v[32];
};

static void _fe25519_reduce_add_sub(struct fe25519 *r)
{
	i_t i;
	i_t j;
	struct espress_cipher_uint32 t[1];
	struct espress_cipher_uint32 const uint32_127[1] = {ESPRESS_CIPHER_UINT32(0, 0, 0, 127)};
	struct espress_cipher_uint32 const uint32_255[1] = {ESPRESS_CIPHER_UINT32(0, 0, 0, 255)};
	for (i = 0 ; i < 4 ; i++)
	{
		espress_cipher_uint32_assign(t, r->v + 31);
		espress_cipher_uint32_shift(t, -7);
		espress_cipher_uint32_and(r->v + 31, uint32_127);
		_times_19(t);
		espress_cipher_uint32_add(r->v + 0, t);
		for (j = 0 ; j < 31 ; j++)
		{
			espress_cipher_uint32_assign(t, r->v + j);
			espress_cipher_uint32_shift(t, -8);
			espress_cipher_uint32_add(r->v + (j + 1), t);
			espress_cipher_uint32_and(r->v + j, uint32_255);
		}
	}
}

static void _fe25519_reduce_mul(struct fe25519 *r)
{
	i_t i;
	i_t j;
	struct espress_cipher_uint32 t[1];
	struct espress_cipher_uint32 const uint32_127[1] = {ESPRESS_CIPHER_UINT32(0, 0, 0, 127)};
	struct espress_cipher_uint32 const uint32_255[1] = {ESPRESS_CIPHER_UINT32(0, 0, 0, 255)};
	for (i = 0 ; i < 2 ; i++)
	{
		espress_cipher_uint32_assign(t, r->v + 31);
		espress_cipher_uint32_shift(t, -7);
		espress_cipher_uint32_and(r->v + 31, uint32_127);
		_times_19(t);
		espress_cipher_uint32_add(r->v + 0, t);
		for (j = 0 ; j < 31 ; j++)
		{
			espress_cipher_uint32_assign(t, r->v + j);
			espress_cipher_uint32_shift(t, -8);
			espress_cipher_uint32_add(r->v + (j + 1), t);
			espress_cipher_uint32_and(r->v + j, uint32_255);
		}
	}
}

static void _fe25519_freeze(struct fe25519 *r)
{
	i_t i;
	struct espress_cipher_uint32 m[1];
	struct espress_cipher_uint32 t[1];
	struct espress_cipher_uint32 const uint32_127[1] = {ESPRESS_CIPHER_UINT32(0, 0, 0, 127)};
	struct espress_cipher_uint32 const uint32_255[1] = {ESPRESS_CIPHER_UINT32(0, 0, 0, 255)};
	struct espress_cipher_uint32 const uint32_237[1] = {ESPRESS_CIPHER_UINT32(0, 0, 0, 237)};
	espress_cipher_uint32_set_u(m, _eq(r->v + 31, uint32_127));
	for (i = 30 ; 0 < i ; i--)
	{
		espress_cipher_uint32_set_u(t, _eq(r->v + i, uint32_255));
		espress_cipher_uint32_and(m, t);
	}
	espress_cipher_uint32_set_u(t, _ge(r->v + 0, uint32_237));
	espress_cipher_uint32_and(m, t);
	espress_cipher_uint32_not(m);
	espress_cipher_uint32_add(m, espress_cipher_uint32_1);
	espress_cipher_uint32_assign(t, m);
	espress_cipher_uint32_and(t, uint32_127);
	espress_cipher_uint32_sub(r->v + 31, t);
	espress_cipher_uint32_assign(t, m);
	espress_cipher_uint32_and(t, uint32_255);
	for (i = 30 ; 0 < i ; i--)
	{
		espress_cipher_uint32_sub(r->v + i, t);
	}
	espress_cipher_uint32_assign(t, m);
	espress_cipher_uint32_and(t, uint32_237);
	espress_cipher_uint32_sub(r->v + 0, t);
}

static void _fe25519_unpack(struct fe25519 *r, b_t const *x)
{
	i_t i;
	struct espress_cipher_uint32 const uint32_127[1] = {ESPRESS_CIPHER_UINT32(0, 0, 0, 127)};
	for (i = 0 ; i < 32 ; i++)
	{
		espress_cipher_uint32_set_u(r->v + i, x[i]);
	}
	espress_cipher_uint32_and(r->v + 31, uint32_127);
}

static void _fe25519_pack(b_t *r, struct fe25519 const *x)
{
	i_t i;
	u_t u;
	struct fe25519 t[1];
	memcpy(t, x, sizeof(*t));
	_fe25519_freeze(t);
	for (i = 0 ; i < 32 ; i++)
	{
		espress_cipher_uint32_get_u(t->v + i, &u);
		r[i] = u;
	}
}

static u_t _fe25519_is_zero(struct fe25519 const *x)
{
	u_t ret;
	i_t i;
	struct fe25519 t[1];
	memcpy(t, x, sizeof(*t));
	_fe25519_freeze(t);
	for (i = 1, ret = _eq(t->v + 0, espress_cipher_uint32_0) ; i < 32 ; i++)
	{
		ret &= _eq(t->v + i, espress_cipher_uint32_0);
	}
	return ret;
}

static u_t _fe25519_is_eq_vartime(struct fe25519 const *x, struct fe25519 const *y)
{
	i_t i;
	struct fe25519 t1[1];
	struct fe25519 t2[1];
	memcpy(t1, x, sizeof(*t1));
	memcpy(t2, y, sizeof(*t2));
	_fe25519_freeze(t1);
	_fe25519_freeze(t2);
	for (i = 0 ; i < 32 ; i++)
	{
		if (!espress_cipher_uint32_eq(t1->v + i, t2->v + i))
		{
			break;
		}
	}
	return (i < 32) ? 0 : 1;
}

static void _fe25519_cmov(struct fe25519 *r, struct fe25519 const *x, b_t b)
{
	i_t i;
	struct espress_cipher_uint32 t[1];
	struct espress_cipher_uint32 mask[1];
	espress_cipher_uint32_set_u(mask, b);
	espress_cipher_uint32_not(mask);
	espress_cipher_uint32_add(mask, espress_cipher_uint32_1);
	for (i = 0 ; i < 32 ; i++)
	{
		espress_cipher_uint32_assign(t, r->v + i);
		espress_cipher_uint32_xor(t, x->v + i);
		espress_cipher_uint32_and(t, mask);
		espress_cipher_uint32_xor(r->v + i, t);
	}
}

static u_t _fe25519_get_parity(struct fe25519 const *x)
{
	u_t ret;
	struct fe25519 t[1];
	memcpy(t, x, sizeof(*t));
	_fe25519_freeze(t);
	espress_cipher_uint32_get_u(t->v + 0, &ret);
	return ret & 1;
}

static void _fe25519_set_one(struct fe25519 *r)
{
	i_t i;
	espress_cipher_uint32_assign(r->v + 0, espress_cipher_uint32_1);
	for (i = 1 ; i < 32 ; i++)
	{
		espress_cipher_uint32_assign(r->v + i, espress_cipher_uint32_0);
	}
}

static void _fe25519_set_zero(struct fe25519 *r)
{
	i_t i;
	for (i = 0 ; i < 32 ; i++)
	{
		espress_cipher_uint32_assign(r->v + i, espress_cipher_uint32_0);
	}
}

static void _fe25519_add(struct fe25519 *r, struct fe25519 const *x)
{
	i_t i;
	for (i = 0 ; i < 32 ; i++)
	{
		espress_cipher_uint32_add(r->v + i, x->v + i);
	}
	_fe25519_reduce_add_sub(r);
}

static void _fe25519_sub(struct fe25519 *r, struct fe25519 const *x)
{
	i_t i;
	struct fe25519 t[1];
	struct espress_cipher_uint32 const uint32_474[1] = {ESPRESS_CIPHER_UINT32(0x00, 0x00, 0x01, 0xda)};
	struct espress_cipher_uint32 const uint32_254[1] = {ESPRESS_CIPHER_UINT32(0x00, 0x00, 0x00, 0xfe)};
	struct espress_cipher_uint32 const uint32_510[1] = {ESPRESS_CIPHER_UINT32(0x00, 0x00, 0x01, 0xfe)};
	espress_cipher_uint32_assign(t->v + 0, r->v + 0);
	espress_cipher_uint32_add(t->v + 0, uint32_474);
	espress_cipher_uint32_assign(t->v + 31, r->v + 31);
	espress_cipher_uint32_add(t->v + 31, uint32_254);
	for (i = 1 ; i < 31 ; i++)
	{
		espress_cipher_uint32_assign(t->v + i, r->v + i);
		espress_cipher_uint32_add(t->v + i, uint32_510);
	}
	for (i = 0 ; i < 32 ; i++)
	{
		espress_cipher_uint32_assign(r->v + i, t->v + i);
		espress_cipher_uint32_sub(r->v + i, x->v + i);
	}
	_fe25519_reduce_add_sub(r);
}

static void _fe25519_neg(struct fe25519 *r)
{
	struct fe25519 t[1];
	memcpy(t, r, sizeof(*t));
	_fe25519_set_zero(r);
	_fe25519_sub(r, t);
}

static void _fe25519_mul(struct fe25519 *r, struct fe25519 const *x)
{
	i_t i;
	i_t j;
	struct espress_cipher_uint32 t1[63];
	struct espress_cipher_uint32 t2[1];
	memset(t1, 0, sizeof(t1));
	for (i = 0 ; i < 32 ; i++)
	{
		for (j = 0 ; j < 32 ; j++)
		{
			espress_cipher_uint32_assign(t2, r->v + i);
			espress_cipher_uint32_mul(t2, x->v + j);
			espress_cipher_uint32_add(t1 + (i + j), t2);
		}
	}
	for (i = 0 ; i < 31 ; i++)
	{
		espress_cipher_uint32_assign(r->v + i, t1 + (i + 32));
		_times_38(r->v + i);
		espress_cipher_uint32_add(r->v + i, t1 + i);
	}
	espress_cipher_uint32_assign(r->v + 31, t1 + 31);
	_fe25519_reduce_mul(r);
}

static void _fe25519_square(struct fe25519 *r)
{
#	if 0 /* strict impl. */
		struct fe25519 t[1];
		memcpy(t, r, sizeof(*t));
		_fe25519_mul(r, t);
#	else
		_fe25519_mul(r, r);
#	endif
}

static void _fe25519_invert(struct fe25519 *r)
{
	i_t i;
	struct fe25519 z2[1];
	struct fe25519 z9[1];
	struct fe25519 z11[1];
	struct fe25519 z2_5_0[1];
	struct fe25519 z2_10_0[1];
	struct fe25519 z2_20_0[1];
	struct fe25519 z2_50_0[1];
	struct fe25519 z2_100_0[1];
	struct fe25519 t[1];

	memcpy(z2, r, sizeof(*z2));
	_fe25519_square(z2);
	memcpy(t, z2, sizeof(*t));
	_fe25519_square(t);
	_fe25519_square(t);
	memcpy(z9, t, sizeof(*z9));
	_fe25519_mul(z9, r);
	memcpy(z11, z9, sizeof(*z11));
	_fe25519_mul(z11, z2);
	memcpy(t, z11, sizeof(*t));
	_fe25519_square(t);
	memcpy(z2_5_0, t, sizeof(*z2_5_0));
	_fe25519_mul(z2_5_0, z9);
	memcpy(t, z2_5_0, sizeof(*t));
	_fe25519_square(t);
	_fe25519_square(t);
	_fe25519_square(t);
	_fe25519_square(t);
	_fe25519_square(t);
	memcpy(z2_10_0, t, sizeof(*z2_10_0));
	_fe25519_mul(z2_10_0, z2_5_0);
	memcpy(t, z2_10_0, sizeof(*t));
	for (i = 0 ; i < 10 ; i ++)
	{
		_fe25519_square(t);
	}
	memcpy(z2_20_0, t, sizeof(*z2_20_0));
	_fe25519_mul(z2_20_0, z2_10_0);
	memcpy(t, z2_20_0, sizeof(*t));
	for (i = 0 ; i < 20 ; i ++)
	{
		_fe25519_square(t);
	}
	_fe25519_mul(t, z2_20_0);
	for (i = 0 ; i < 10 ; i ++)
	{
		_fe25519_square(t);
	}
	memcpy(z2_50_0, t, sizeof(*z2_50_0));
	_fe25519_mul(z2_50_0, z2_10_0);
	memcpy(t, z2_50_0, sizeof(*t));
	for (i = 0 ; i < 50 ; i ++)
	{
		_fe25519_square(t);
	}
	memcpy(z2_100_0, t, sizeof(*z2_100_0));
	_fe25519_mul(z2_100_0, z2_50_0);
	memcpy(t, z2_100_0, sizeof(*t));
	for (i = 0 ; i < 100 ; i ++)
	{
		_fe25519_square(t);
	}
	_fe25519_mul(t, z2_100_0);
	for (i = 0 ; i < 50 ; i ++)
	{
		_fe25519_square(t);
	}
	_fe25519_mul(t, z2_50_0);
	_fe25519_square(t);
	_fe25519_square(t);
	_fe25519_square(t);
	_fe25519_square(t);
	_fe25519_square(t);
	memcpy(r, t, sizeof(*r));
	_fe25519_mul(r, z11);
}

static void _fe25519_pow2523(struct fe25519 *r)
{
	i_t i;
	struct fe25519 z2[1];
	struct fe25519 z9[1];
	struct fe25519 z11[1];
	struct fe25519 z2_5_0[1];
	struct fe25519 z2_10_0[1];
	struct fe25519 z2_20_0[1];
	struct fe25519 z2_50_0[1];
	struct fe25519 z2_100_0[1];
	struct fe25519 t[1];

	memcpy(z2, r, sizeof(*z2));
	_fe25519_square(z2);
	memcpy(t, z2, sizeof(*t));
	_fe25519_square(t);
	_fe25519_square(t);
	memcpy(z9, t, sizeof(*z9));
	_fe25519_mul(z9, r);
	memcpy(z11, z9, sizeof(*z11));
	_fe25519_mul(z11, z2);
	memcpy(t, z11, sizeof(*t));
	_fe25519_square(t);
	memcpy(z2_5_0, t, sizeof(*z2_5_0));
	_fe25519_mul(z2_5_0, z9);
	memcpy(t, z2_5_0, sizeof(*t));
	_fe25519_square(t);
	_fe25519_square(t);
	_fe25519_square(t);
	_fe25519_square(t);
	_fe25519_square(t);
	memcpy(z2_10_0, t, sizeof(*z2_10_0));
	_fe25519_mul(z2_10_0, z2_5_0);
	memcpy(t, z2_10_0, sizeof(*t));
	for (i = 0 ; i < 10 ; i++)
	{
		_fe25519_square(t);
	}
	memcpy(z2_20_0, t, sizeof(z2_20_0));
	_fe25519_mul(z2_20_0, z2_10_0);
	memcpy(t, z2_20_0, sizeof(*t));
	for (i = 0 ; i < 20 ; i++)
	{
		_fe25519_square(t);
	}
	_fe25519_mul(t, z2_20_0);
	for (i = 0 ; i < 10 ; i++)
	{
		_fe25519_square(t);
	}
	memcpy(z2_50_0, t, sizeof(*z2_50_0));
	_fe25519_mul(z2_50_0, z2_10_0);
	memcpy(t, z2_50_0, sizeof(*t));
	for (i = 0 ; i < 50 ; i++)
	{
		_fe25519_square(t);
	}
	memcpy(z2_100_0, t, sizeof(*z2_100_0));
	_fe25519_mul(z2_100_0, z2_50_0);
	memcpy(t, z2_100_0, sizeof(*t));
	for (i = 0 ; i < 100 ; i++)
	{
		_fe25519_square(t);
	}
	_fe25519_mul(t, z2_100_0);
	for (i = 0 ; i < 50 ; i++)
	{
		_fe25519_square(t);
	}
	_fe25519_mul(t, z2_50_0);
	_fe25519_square(t);
	_fe25519_square(t);
	_fe25519_mul(r, t);
}

