static void _sc25519_reduce_add_sub(struct sc25519 *r)
{
	i_t i;
	struct espress_cipher_uint32 pb[1] = {ESPRESS_CIPHER_UINT32(0, 0, 0, 0)};
	struct espress_cipher_uint32 b[1];
	struct espress_cipher_uint32 mask[1];
	struct espress_cipher_uint32 t[32];

	for(i = 0 ; i < 32 ; i++)
	{
		espress_cipher_uint32_add(pb, _sc25519_m + i);
		espress_cipher_uint32_set_u(b, _lt(r->v + i, pb));
		espress_cipher_uint32_assign(t + i, b);
		espress_cipher_uint32_shift(t + i, 8);
		espress_cipher_uint32_add(t + i, r->v + i);
		espress_cipher_uint32_sub(t + i, pb);
		espress_cipher_uint32_assign(pb, b);
	}
	espress_cipher_uint32_assign(mask, b);
	espress_cipher_uint32_sub(mask, espress_cipher_uint32_1);
	for (i = 0 ; i < 32 ; i++)
	{
		espress_cipher_uint32_xor(t + i, r->v + i);
		espress_cipher_uint32_and(t + i, mask);
		espress_cipher_uint32_xor(r->v + i, t + i);
	}
}

static void _sc25519_barrett_reduce(struct sc25519 *r, struct espress_cipher_uint32 const *x)
{
	i_t i;
	i_t j;
	struct espress_cipher_uint32 t[1];
	struct espress_cipher_uint32 q2[66];
	struct espress_cipher_uint32 *q3 = q2 + 33;
	struct espress_cipher_uint32 r1[33];
	struct espress_cipher_uint32 r2[33];
	struct espress_cipher_uint32 carry[1];
	struct espress_cipher_uint32 pb[1] = {ESPRESS_CIPHER_UINT32(0, 0, 0, 0)};
	struct espress_cipher_uint32 b[1];
	struct espress_cipher_uint32 const uint32_255[1] = {ESPRESS_CIPHER_UINT32(0, 0, 0, 0xff)};

	memset(q2, 0, sizeof(q2));
	memset(r2, 0, sizeof(r2));

	for (i = 0 ; i < 33 ; i++)
	{
		for (j = 0 ; j < 33 ; j++)
		{
			if (31 <= (i + j))
			{
				espress_cipher_uint32_assign(t, _sc25519_mu + i);
				espress_cipher_uint32_mul(t, x + (j + 31));
				espress_cipher_uint32_add(q2 + (i + j), t);
			}
		}
	}
	espress_cipher_uint32_assign(carry, q2 + 31);
	espress_cipher_uint32_shift(carry, -8);
	espress_cipher_uint32_add(q2 + 32, carry);
	espress_cipher_uint32_assign(carry, q2 + 32);
	espress_cipher_uint32_shift(carry, -8);
	espress_cipher_uint32_add(q2 + 33, carry);

	for (i = 0 ; i < 33 ; i++)
	{
		espress_cipher_uint32_assign(r1 + i, x + i);
	}
	for (i = 0 ; i < 32 ; i++)
	{
		for (j = 0 ; j < 33 ; j++)
		{
			if ((i + j) < 33)
			{
				espress_cipher_uint32_assign(t, _sc25519_m + i);
				espress_cipher_uint32_mul(t, q3 + j);
				espress_cipher_uint32_add(r2 + (i + j), t);
			}
		}
	}

	for (i = 0 ; i < 32 ; i++)
	{
		espress_cipher_uint32_assign(carry, r2 + i);
		espress_cipher_uint32_shift(carry, -8);
		espress_cipher_uint32_add(r2 + (i + 1), carry);
		espress_cipher_uint32_and(r2 + i, uint32_255);
	}

	for (i = 0 ; i < 32 ; i++)
	{
		espress_cipher_uint32_add(pb, r2 + i);
		espress_cipher_uint32_set_u(b, _lt(r1 + i, pb));
		espress_cipher_uint32_assign(r->v + i, b);
		espress_cipher_uint32_shift(r->v + i, 8);
		espress_cipher_uint32_add(r->v + i, r1 + i);
		espress_cipher_uint32_sub(r->v + i, pb);
		espress_cipher_uint32_assign(pb, b);
	}

	_sc25519_reduce_add_sub(r);
	_sc25519_reduce_add_sub(r);
}

static void _sc25519_from_32bytes(struct sc25519 *r, b_t const *x)
{
	i_t i;
	struct espress_cipher_uint32 t[64];
	for (i = 0 ; i < 32 ; i++)
	{
		espress_cipher_uint32_set_u(t + i, x[i]);
	}
	memset(t + 32, 0, sizeof(t) >> 1);
	_sc25519_barrett_reduce(r, t);
}

static void _sc25519_from_64bytes(struct sc25519 *r, b_t const *x)
{
	i_t i;
	struct espress_cipher_uint32 t[64];
	for (i = 0 ; i < 64 ; i++)
	{
		espress_cipher_uint32_set_u(t + i, x[i]);
	}
	_sc25519_barrett_reduce(r, t);
}

static void _sc25519_to_32bytes(b_t *r, struct sc25519 const *x)
{
	i_t i;
	u_t u;
	for (i = 0 ; i < 32 ; i++)
	{
		espress_cipher_uint32_get_u(x->v + i, &u);
		r[i] = u;
	}
}

static void _sc25519_add(struct sc25519 *r, struct sc25519 const *x)
{
	i_t i;
	struct espress_cipher_uint32 carry[1];
	struct espress_cipher_uint32 const uint32_255[1] = {ESPRESS_CIPHER_UINT32(0, 0, 0, 0xff)};
	for (i = 0 ; i < 32 ; i++)
	{
		espress_cipher_uint32_add(r->v + i, x->v + i);
	}
	for (i = 0 ; i < 31 ; i++)
	{
		espress_cipher_uint32_assign(carry, r->v + i);
		espress_cipher_uint32_shift(carry, -8);
		espress_cipher_uint32_add(r->v + (i + 1), carry);
		espress_cipher_uint32_and(r->v + i, uint32_255);
	}
	_sc25519_reduce_add_sub(r);
}

static void _sc25519_mul(struct sc25519 *r, struct sc25519 const *x)
{
	i_t i;
	i_t j;
	struct espress_cipher_uint32 carry[1];
	struct espress_cipher_uint32 t1[64];
	struct espress_cipher_uint32 t2[1];
	struct espress_cipher_uint32 const uint32_255[1] = {ESPRESS_CIPHER_UINT32(0, 0, 0, 0xff)};

	memset(t1, 0, sizeof(t1));

	for (i = 0 ; i < 32 ; i++)
	{
		for (j = 0 ; j < 32 ; j++)
		{
			espress_cipher_uint32_assign(t2, r->v + i);
			espress_cipher_uint32_mul(t2, x->v + j);
			espress_cipher_uint32_add(t1 + (i + j), t2);
		}
	}

	for (i = 0 ; i < 63 ; i++)
	{
		espress_cipher_uint32_assign(carry, t1 + i);
		espress_cipher_uint32_shift(carry, -8);
		espress_cipher_uint32_add(t1 + (i + 1), carry);
		espress_cipher_uint32_and(t1 + i, uint32_255);
	}

	_sc25519_barrett_reduce(r, t1);
}

static void _sc25519_window_3(c_t *r, struct sc25519 const *s)
{
	i_t i;
	u_t u;
	c_t carry;

	for (i = 0 ; i < 10 ; i++)
	{
		espress_cipher_uint32_get_u(s->v + (3 * i + 0), &u); r[8 * i + 0]  =  u       & 7;
		                                                     r[8 * i + 1]  = (u >> 3) & 7;
		                                                     r[8 * i + 2]  = (u >> 6) & 7;
		espress_cipher_uint32_get_u(s->v + (3 * i + 1), &u); r[8 * i + 2] ^= (u << 2) & 7;
		                                                     r[8 * i + 3]  = (u >> 1) & 7;
		                                                     r[8 * i + 4]  = (u >> 4) & 7;
		                                                     r[8 * i + 5]  = (u >> 7) & 7;
		espress_cipher_uint32_get_u(s->v + (3 * i + 2), &u); r[8 * i + 5] ^= (u << 1) & 7;
		                                                     r[8 * i + 6]  = (u >> 2) & 7;
		                                                     r[8 * i + 7]  = (u >> 5) & 7;
	}
	espress_cipher_uint32_get_u(s->v + (3 * i + 0), &u); r[8 * i + 0]  =  u       & 7;
	                                                     r[8 * i + 1]  = (u >> 3) & 7;
	                                                     r[8 * i + 2]  = (u >> 6) & 7;
	espress_cipher_uint32_get_u(s->v + (3 * i + 1), &u); r[8 * i + 2] ^= (u << 2) & 7;
	                                                     r[8 * i + 3]  = (u >> 1) & 7;
	                                                     r[8 * i + 4]  = (u >> 4) & 7;

	for (i = 0, carry = 0 ; i < 84 ; i++)
	{
		r[i] += carry;
		r[i + 1] += r[i] >> 3;
		r[i] &= 7;
		carry = r[i] >> 2;
		r[i] -= carry << 3;
	}
	r[84] += carry;
}

static void _sc25519_2_interleave_2(b_t *r, struct sc25519 const *s1, struct sc25519 const *s2)
{
	i_t i;
	u_t u1;
	u_t u2;
	for (i = 0 ; i < 31 ; i++)
	{
		espress_cipher_uint32_get_u(s1->v + i, &u1);
		espress_cipher_uint32_get_u(s2->v + i, &u2);
		r[4 * i    ] = ( u1       & 3) ^ (( u2       & 3) << 2);
		r[4 * i + 1] = ((u1 >> 2) & 3) ^ (((u2 >> 2) & 3) << 2);
		r[4 * i + 2] = ((u1 >> 4) & 3) ^ (((u2 >> 4) & 3) << 2);
		r[4 * i + 3] = ((u1 >> 6) & 3) ^ (((u2 >> 6) & 3) << 2);
	}
	espress_cipher_uint32_get_u(s1->v + 31, &u1);
	espress_cipher_uint32_get_u(s2->v + 31, &u2);
	r[124] = ( u1       & 3) ^ (( u2       & 3) << 2);
	r[125] = ((u1 >> 2) & 3) ^ (((u2 >> 2) & 3) << 2);
	r[126] = ((u1 >> 4) & 3) ^ (((u2 >> 4) & 3) << 2);
}

