static void _ge25519_p1p1_to_p2(struct ge25519_p2 *r, struct ge25519_p1p1 const *p)
{
	memcpy(r->x, p->x, sizeof(*(r->x)));
	_fe25519_mul(r->x, p->t);
	memcpy(r->y, p->y, sizeof(*(r->y)));
	_fe25519_mul(r->y, p->z);
	memcpy(r->z, p->z, sizeof(*(r->z)));
	_fe25519_mul(r->z, p->t);
}

static void _ge25519_p1p1_to_p3(struct ge25519_p3 *r, struct ge25519_p1p1 const *p)
{
	_ge25519_p1p1_to_p2((struct ge25519_p2 *)r, p);
	memcpy(r->t, p->x, sizeof(*(r->t)));
	_fe25519_mul(r->t, p->y);
}

static void _ge25519_mix_add_2(struct ge25519_p3 *r, struct ge25519_aff const *q)
{
	struct fe25519 a[1];
	struct fe25519 b[1];
	struct fe25519 t1[1];
	struct fe25519 t2[1];
	struct fe25519 c[1];
	struct fe25519 d[1];
	struct fe25519 e[1];
	struct fe25519 f[1];
	struct fe25519 g[1];
	struct fe25519 h[1];
	struct fe25519 qt[1];

	memcpy(qt, q->x, sizeof(*qt));
	_fe25519_mul(qt, q->y);
	memcpy(a, r->y, sizeof(*a));
	_fe25519_sub(a, r->x);
	memcpy(b, r->y, sizeof(*b));
	_fe25519_add(b, r->x);
	memcpy(t1, q->y, sizeof(*t1));
	_fe25519_sub(t1, q->x);
	memcpy(t2, q->y, sizeof(t2));
	_fe25519_add(t2, q->x);
	_fe25519_mul(a, t1);
	_fe25519_mul(b, t2);
	memcpy(e, b, sizeof(*e));
	_fe25519_sub(e, a);
	memcpy(h, b, sizeof(*h));
	_fe25519_add(h, a);
	memcpy(c, r->t, sizeof(*c));
	_fe25519_mul(c, qt);
	_fe25519_mul(c, _ge25519_ec2d);
	memcpy(d, r->z, sizeof(*d));
	_fe25519_add(d, r->z);
	memcpy(f, d, sizeof(*f));
	_fe25519_sub(f, c);
	memcpy(g, d, sizeof(*g));
	_fe25519_add(g, c);
	memcpy(r->x, e, sizeof(*(r->x)));
	_fe25519_mul(r->x, f);
	memcpy(r->y, h, sizeof(*(r->y)));
	_fe25519_mul(r->y, g);
	memcpy(r->z, g, sizeof(*(r->z)));
	_fe25519_mul(r->z, f);
	memcpy(r->t, e, sizeof(*(r->t)));
	_fe25519_mul(r->t, h);
}

static void _ge25519_add_p1p1(struct ge25519_p1p1 *r, struct ge25519_p3 const *p, struct ge25519_p3 const *q)
{
	struct fe25519 a[1];
	struct fe25519 b[1];
	struct fe25519 c[1];
	struct fe25519 d[1];
	struct fe25519 t1[1];
	struct fe25519 t2[1];

	memcpy(a, p->y, sizeof(*a));
	_fe25519_sub(a, p->x);
	memcpy(t1, q->y, sizeof(*t1));
	_fe25519_sub(t1, q->x);
	_fe25519_mul(a, t1);
	memcpy(b, p->x, sizeof(*b));
	_fe25519_add(b, p->y);
	memcpy(t1, q->x, sizeof(*t1));
	_fe25519_add(t1, q->y);
	_fe25519_mul(b, t1);
	memcpy(c, p->t, sizeof(*c));
	_fe25519_mul(c, q->t);
	_fe25519_mul(c, _ge25519_ec2d);
	memcpy(d, p->z, sizeof(*d));
	_fe25519_mul(d, q->z);
	memcpy(t2, d, sizeof(*t2));
	_fe25519_add(d, t2);
	memcpy(r->x, b, sizeof(*(r->x)));
	_fe25519_sub(r->x, a);
	memcpy(r->t, d, sizeof(*(r->t)));
	_fe25519_sub(r->t, c);
	memcpy(r->z, d, sizeof(*(r->z)));
	_fe25519_add(r->z, c);
	memcpy(r->y, b, sizeof(*(r->y)));
	_fe25519_add(r->y, a);
}

static void _ge25519_dbl_p1p1(struct ge25519_p1p1 *r, struct ge25519_p2 const *p)
{
	struct fe25519 a[1];
	struct fe25519 b[1];
	struct fe25519 c[1];
	struct fe25519 d[1];
	struct fe25519 t[1];
  
	memcpy(a, p->x, sizeof(*a));
	_fe25519_square(a);
	memcpy(b, p->y, sizeof(*b));
	_fe25519_square(b);
	memcpy(c, p->z, sizeof(*c));
	_fe25519_square(c);
	memcpy(t, c, sizeof(*t));
	_fe25519_add(c, t);
	memcpy(d, a, sizeof(*d));
	_fe25519_neg(d);
	memcpy(r->x, p->x, sizeof(*(r->x)));
	_fe25519_add(r->x, p->y);
	_fe25519_square(r->x);
	_fe25519_sub(r->x, a);
	_fe25519_sub(r->x, b);
	memcpy(r->z, d, sizeof(*(r->z)));
	_fe25519_add(r->z, b);
	memcpy(r->t, r->z, sizeof(*(r->t)));
	_fe25519_sub(r->t, c);
	memcpy(r->y, d, sizeof(*(r->y)));
	_fe25519_sub(r->y, b);
}

static void _ge25519_cmov_aff(struct ge25519_aff *r, struct ge25519_aff const *p, b_t b)
{
	_fe25519_cmov(r->x, p->x, b);
	_fe25519_cmov(r->y, p->y, b);
}

static b_t _equal(c_t b, c_t c)
{
	u_t u;
	b_t ub = b;
	b_t uc = c;
	b_t x = ub ^ uc;
	struct espress_cipher_uint32 y[1];
	espress_cipher_uint32_set_u(y, x);
	espress_cipher_uint32_sub(y, espress_cipher_uint32_1);
	espress_cipher_uint32_shift(y, -31);
	espress_cipher_uint32_get_u(y, &u);
	return u;
}

static b_t _negative(c_t b)
{
	b_t ub = b;
	b_t x = ub >> 7;
	return x;
}

static void _ge25519_choose_t(struct ge25519_aff *t, u_t pos, c_t b)
{
	struct fe25519 v[1];
	memcpy(t, _ge25519_base_multiples_affine + (5 * pos + 0), sizeof(*t));
	_ge25519_cmov_aff(t, _ge25519_base_multiples_affine + (5 * pos + 1), _equal(b, 1) | _equal(b, -1));
	_ge25519_cmov_aff(t, _ge25519_base_multiples_affine + (5 * pos + 2), _equal(b, 2) | _equal(b, -2));
	_ge25519_cmov_aff(t, _ge25519_base_multiples_affine + (5 * pos + 3), _equal(b, 3) | _equal(b, -3));
	_ge25519_cmov_aff(t, _ge25519_base_multiples_affine + (5 * pos + 4),                _equal(b, -4));
	memcpy(v, t->x, sizeof(*v));
	_fe25519_neg(v);
	_fe25519_cmov(t->x, v, _negative(b));
}

static void _ge25519_set_neutral(struct ge25519 *r)
{
  _fe25519_set_zero(r->x);
  _fe25519_set_one(r->y);
  _fe25519_set_one(r->z);
  _fe25519_set_zero(r->t);
}

static i_t _ge25519_unpackneg_vartime(struct ge25519_p3 *r, b_t const *p)
{
	i_t ret = 0;
	u_t par;
	struct fe25519 t[1];
	struct fe25519 chk[1];
	struct fe25519 num[1];
	struct fe25519 den[1];
	struct fe25519 den2[1];
	struct fe25519 den4[1];
	struct fe25519 den6[1];

	_fe25519_set_one(r->z);
	par = p[31] >> 7;
	_fe25519_unpack(r->y, p);
	memcpy(num, r->y, sizeof(*num));
	_fe25519_square(num);
	memcpy(den, num, sizeof(*den));
	_fe25519_mul(den, _ge25519_ecd);
	_fe25519_sub(num, r->z);
	_fe25519_add(den, r->z);

	memcpy(den2, den, sizeof(*den2));
	_fe25519_square(den2);
	memcpy(den4, den2, sizeof(*den4));
	_fe25519_square(den4);
	memcpy(den6, den4, sizeof(*den6));
	_fe25519_mul(den6, den2);
	memcpy(t, den6, sizeof(*t));
	_fe25519_mul(t, num);
	_fe25519_mul(t, den);

	_fe25519_pow2523(t);
	_fe25519_mul(t, num);
	_fe25519_mul(t, den);
	_fe25519_mul(t, den);
	memcpy(r->x, t, sizeof(*(r->x)));
	_fe25519_mul(r->x, den);

	memcpy(chk, r->x, sizeof(*chk));
	_fe25519_square(chk);
	_fe25519_mul(chk, den);
	if (!_fe25519_is_eq_vartime(chk, num))
	{
		_fe25519_mul(r->x, _ge25519_sqrtm1);
	}

	memcpy(chk, r->x, sizeof(*chk));
	_fe25519_square(chk);
	_fe25519_mul(chk, den);
	if (!_fe25519_is_eq_vartime(chk, num))
	{
		ret = 1;
		goto EXIT;
	}

	if ((1 - par) != _fe25519_get_parity(r->x))
	{
		_fe25519_neg(r->x);
	}

	memcpy(r->t, r->x, sizeof(*(r->t)));
	_fe25519_mul(r->t, r->y);

EXIT:

	return ret;
}

static void _ge25519_pack(b_t *r, struct ge25519_p3 const *p)
{
	struct fe25519 tx[1];
	struct fe25519 ty[1];
	struct fe25519 zi[1];
	memcpy(zi, p->z, sizeof(*zi));
	_fe25519_invert(zi);
	memcpy(tx, p->x, sizeof(*tx));
	_fe25519_mul(tx, zi);
	memcpy(ty, p->y, sizeof(*ty));
	_fe25519_mul(ty, zi);
	_fe25519_pack(r, ty);
	r[31] ^= _fe25519_get_parity(tx) << 7;
}

i_t _ge25519_is_neutral_vartime(struct ge25519_p3 const *p)
{
	i_t ret = 1;
	if (!_fe25519_is_zero(p->x))
	{
		ret = 0;
	}
	if (!_fe25519_is_eq_vartime(p->y, p->z))
	{
		ret = 0;
	}
	return ret;
}

static void _ge25519_double_scalarmult_vartime(struct ge25519_p3 *r, struct ge25519_p3 const *p1, struct sc25519 const *s1, struct ge25519_p3 const *p2, struct sc25519 const *s2)
{
	i_t i;
	b_t b[127];
	struct ge25519_p1p1 tp1p1[1];
	struct ge25519_p3 pre[16];

	_ge25519_set_neutral((struct ge25519 *)pre);
	memcpy(pre + 1, p1, sizeof(*pre));
	_ge25519_dbl_p1p1(tp1p1, (struct ge25519_p2 *)p1);        _ge25519_p1p1_to_p3(pre +  2, tp1p1);
	_ge25519_add_p1p1(tp1p1, pre + 1, pre +  2);              _ge25519_p1p1_to_p3(pre +  3, tp1p1);
	memcpy(pre + 4, p2, sizeof(*pre));
	_ge25519_add_p1p1(tp1p1, pre + 1, pre +  4);              _ge25519_p1p1_to_p3(pre +  5, tp1p1);
	_ge25519_add_p1p1(tp1p1, pre + 2, pre +  4);              _ge25519_p1p1_to_p3(pre +  6, tp1p1);
	_ge25519_add_p1p1(tp1p1, pre + 3, pre +  4);              _ge25519_p1p1_to_p3(pre +  7, tp1p1);
	_ge25519_dbl_p1p1(tp1p1,(struct ge25519_p2 *)p2);         _ge25519_p1p1_to_p3(pre +  8, tp1p1);
	_ge25519_add_p1p1(tp1p1, pre + 1, pre +  8);              _ge25519_p1p1_to_p3(pre +  9, tp1p1);
	_ge25519_dbl_p1p1(tp1p1, (struct ge25519_p2 *)(pre + 5)); _ge25519_p1p1_to_p3(pre + 10, tp1p1);
	_ge25519_add_p1p1(tp1p1, pre + 3, pre +  8);              _ge25519_p1p1_to_p3(pre + 11, tp1p1);
	_ge25519_add_p1p1(tp1p1, pre + 4, pre +  8);              _ge25519_p1p1_to_p3(pre + 12, tp1p1);
	_ge25519_add_p1p1(tp1p1, pre + 1, pre + 12);              _ge25519_p1p1_to_p3(pre + 13, tp1p1);
	_ge25519_add_p1p1(tp1p1, pre + 2, pre + 12);              _ge25519_p1p1_to_p3(pre + 14, tp1p1);
	_ge25519_add_p1p1(tp1p1, pre + 3, pre + 12);              _ge25519_p1p1_to_p3(pre + 15, tp1p1);

	_sc25519_2_interleave_2(b, s1, s2);

	memcpy(r, pre + b[126], sizeof(*r));
	for (i = 125 ; 0 <= i ; i--)
	{
		_ge25519_dbl_p1p1(tp1p1, (struct ge25519_p2 *)r);
		_ge25519_p1p1_to_p2((struct ge25519_p2 *)r, tp1p1);
		_ge25519_dbl_p1p1(tp1p1, (struct ge25519_p2 *)r);
		if (0 != b[i])
		{
			_ge25519_p1p1_to_p3(r, tp1p1);
			_ge25519_add_p1p1(tp1p1, r, pre + b[i]);
		}
		if (0 != i)
		{
			_ge25519_p1p1_to_p2((struct ge25519_p2 *)r, tp1p1);
		}
		else
		{
			_ge25519_p1p1_to_p3(r, tp1p1);
		}
	}
}

static void _ge25519_scalar_mult_base(struct ge25519_p3 *r, struct sc25519 const *s)
{
	i_t i;
	c_t b[85];
	struct ge25519_aff t[1];
	_sc25519_window_3(b, s);

	_ge25519_choose_t((struct ge25519_aff *)r, 0, b[0]);
	_fe25519_set_one(r->z);
	memcpy(r->t, r->x, sizeof(*(r->t)));
	_fe25519_mul(r->t, r->y);
	for(i = 1 ; i < 85 ; i++)
	{
		_ge25519_choose_t(t, i, b[i]);
		_ge25519_mix_add_2(r, t);
	}
}

static void _ed25519_keypair(b_t *pk, b_t const *sk)
{
	struct espress_cipher_sha512 h[1];
	b_t az[64];
	struct sc25519 scsk[1];
	struct ge25519 gepk[1];

	espress_cipher_sha512->initialize(h);
	espress_cipher_sha512->update(h, sk, 32);
	espress_cipher_sha512->finalize(h, az);
	az[0] &= 248;
	az[31] &= 127;
	az[31] |= 64;

	_sc25519_from_32bytes(scsk, az);

	_ge25519_scalar_mult_base((struct ge25519_p3 *)gepk, scsk);
	_ge25519_pack(pk, (struct ge25519_p3 *)gepk);
}

static void _ed25519_sign(b_t *sig, b_t const *sk, b_t const *pk, b_t const *m, u_t mlen)
{
	struct espress_cipher_sha512 h[1];
	b_t az[64];
	b_t nonce[64];
	b_t hram[64];
	struct sc25519 sck[1];
	struct sc25519 scs[1];
	struct sc25519 scsk[1];
	struct ge25519 ger[1];

	espress_cipher_sha512->initialize(h);
	espress_cipher_sha512->update(h, sk, 32);
	espress_cipher_sha512->finalize(h, az);
	az[0] &= 248;
	az[31] &= 127;
	az[31] |= 64;

	espress_cipher_sha512->initialize(h);
	espress_cipher_sha512->update(h, az + 32, 32);
	espress_cipher_sha512->update(h, m, mlen);
	espress_cipher_sha512->finalize(h, nonce);

	_sc25519_from_64bytes(sck, nonce);
	_ge25519_scalar_mult_base((struct ge25519_p3 *)ger, sck);
	_ge25519_pack(sig, (struct ge25519_p3 *)ger);

	espress_cipher_sha512->initialize(h);
	espress_cipher_sha512->update(h, sig, 32);
	espress_cipher_sha512->update(h, pk, 32);
	espress_cipher_sha512->update(h, m, mlen);
	espress_cipher_sha512->finalize(h, hram);

	_sc25519_from_64bytes(scs, hram);
	_sc25519_from_32bytes(scsk, az);
	_sc25519_mul(scs, scsk);
	_sc25519_add(scs, sck);

	_sc25519_to_32bytes(sig + 32, scs);
}

static i_t _ed25519_open(b_t const *sig, b_t const *pk, b_t const *m, u_t mlen)
{
	i_t ret = 0;
	struct espress_cipher_sha512 h[1];
	b_t pkcopy[32];
	b_t rcopy[32];
	b_t hram[64];
	b_t rcheck[32];
	struct ge25519 get1[1];
	struct ge25519 get2[1];
	struct sc25519 schram[1];
	struct sc25519 scs[1];

	if (0 != (sig[63] & 224))
	{
		ret = 1;
		goto EXIT;
	}
	if (_ge25519_unpackneg_vartime((struct ge25519_p3 *)get1, pk))
	{
		ret = 1;
		goto EXIT;
	}

	memmove(pkcopy, pk, 32);
	memmove(rcopy, sig, 32);

	_sc25519_from_32bytes(scs, sig + 32);

	espress_cipher_sha512->initialize(h);
	espress_cipher_sha512->update(h, sig, 32);
	espress_cipher_sha512->update(h, pkcopy, 32);
	espress_cipher_sha512->update(h, m, mlen);
	espress_cipher_sha512->finalize(h, hram);

	_sc25519_from_64bytes(schram, hram);

	_ge25519_double_scalarmult_vartime((struct ge25519_p3 *)get2, (struct ge25519_p3 *)get1, schram, (struct ge25519_p3 *)_ge25519_base, scs);
	_ge25519_pack(rcheck, (struct ge25519_p3 *)get2);

	ret = _crypto_verify_32(rcopy, rcheck);

EXIT:

	return ret;
}

static void _get_public_key(b_t *public_key, b_t const *secret_key)
{
	_ed25519_keypair(public_key, secret_key);
}

static void _sign(b_t *signature, b_t const *secret_key, b_t const *public_key, b_t const *message, u_t message_size)
{
	_ed25519_sign(signature, secret_key, public_key, message, message_size);
}

static i_t _auth(b_t const *signature, b_t const *public_key, b_t const *message, u_t message_size)
{
	return _ed25519_open(signature, public_key, message, message_size);
}
